import { defineCollection, z } from 'astro:content';

const projects = defineCollection({
  type: 'content',
  schema: ({ image }) =>
    z.object({
      title: z.string(),
      summary: z.string(),
      tags: z.array(z.string()).min(1),
      href: z.string().url(),
      repo: z.string().url().optional(),
      order: z.number().int().nonnegative(),
      featured: z.boolean().default(true),
      motion: z.enum(['ripple', 'years']).optional(),
      // One still picture that shows the project at a glance, generated by scripts/work-art.
      art: z
        .object({
          image: image(),
          alt: z.string().min(1)
        })
        .optional()
    })
});

export const collections = {
  projects
};
